declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('dashboard.customize');header('Content-Type: application/json; charset=UTF-8');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['success'=>false]);exit;}verify_csrf();$layout=json_decode((string)($_POST['layout']??''),true);if(!is_array($layout)){http_response_code(422);echo json_encode(['success'=>false,'error'=>'Formato inválido']);exit;}$clean=[];foreach(array_slice($layout,0,30)as$i=>$w){$id=preg_replace('/[^a-z0-9_-]/i','',(string)($w['id']??''));$size=(string)($w['size']??'medium');if($id===''||!in_array($size,['small','medium','large','full'],true))continue;$clean[]=['id'=>$id,'size'=>$size,'order'=>$i];}db()->prepare('INSERT INTO dashboard_preferences(user_id,layout_json) VALUES (?,?) ON DUPLICATE KEY UPDATE layout_json=VALUES(layout_json)')->execute([(int)$_SESSION['user_id'],json_encode($clean,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);echo json_encode(['success'=>true]);
